parameters.jsCode:
const rawOutput = $json.output;

if (!rawOutput) {
  throw new Error("No output received from Final Interview Report Agent.");
}

let text = String(rawOutput).trim();

// Remove markdown code fences if present
text = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Find JSON object
const start = text.indexOf("{");
const end = text.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("Could not find JSON object in Agent 5 output.");
}

const jsonText = text.substring(start, end + 1);

let report;

try {
  report = JSON.parse(jsonText);
} catch (error) {
  throw new Error(
    "Invalid JSON returned by Agent 5: " + error.message
  );
}

return [
  {
    json: report
  }
];
